	@ParameterizedTest
	@ValueSource(ints = { 1, -1 })
	void sampledZeroOutputStillBoundsMatchingPayloadAndConsumedMaterialization(int limit) throws Exception {
		Measured measured = measure(limit, false);
		assertThat(measured.buildRows()).as("actual complete hash input").isEqualTo(BUILD_ROWS);
		assertThat(measured.probeRows()).as("actual probe records, not the sampled join cardinality")
				.isEqualTo(PROBE_ROWS);
		assertThat(measured.producedRows()).as("the first bridge fill retains all 16 actual matching payloads")
				.isEqualTo(BUILD_ROWS);
		assertThat(measured.consumedRows()).isEqualTo(limit < 0 ? BUILD_ROWS : limit);
		assertAll(
				() -> assertThat(measured.features().high(Feature.INTERPRETED_ROW))
						.as("the hash quote counts build/probe producers and matching-payload visits separately")
						.isGreaterThanOrEqualTo(measured.buildRows() + measured.probeRows() + measured.producedRows()),
				() -> assertThat(measured.features().high(Feature.OUTPUT_MATERIALIZATION))
						.as("sampled zero is not exact-empty proof for the consumer's actual BindingSets")
						.isGreaterThanOrEqualTo(measured.consumedRows()));
	}

	private static IRI subject(int index) {
		return SimpleValueFactory.getInstance().createIRI(NS + "s" + index);
	}

	private Measured measure(int limit, boolean empty) throws Exception {
		String query = QUERY + (limit < 0 ? "" : " LIMIT " + limit);
		Map<Value, Integer> expected = empty ? Map.of() : Map.of(VALUE, limit < 0 ? BUILD_ROWS : limit);
		assertThat(bag(memoryRepository, query)).as("MemoryStore exact bag").isEqualTo(expected);
		set(NATIVE, "false");
		assertThat(bag(repository, query)).as("generic LMDB exact bag").isEqualTo(expected);
		set(NATIVE, "true");
		Optimized optimized = optimizeAndRun(query);
		try (SailDataset dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			NativeLmdbQuerySource actual = (NativeLmdbQuerySource) dataset;
			CountedSource counted = new CountedSource(actual, actual.idOf(BUILD), actual.idOf(PROBE));
			assertThat(actual.count(UNKNOWN, counted.buildPredicate, UNKNOWN, UNKNOWN)).isEqualTo(BUILD_ROWS);
			if (!empty) {
				assertThat(actual.meanFanOut(counted.buildPredicate, true)).isPresent();
				assertThat(actual.meanFanOut(counted.buildPredicate, true).orElseThrow())
						.as("actual production sample, not injected zero")
						.isZero();
			}
			var triples = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
			LmdbNativeEvaluationStrategy strategy = spy(new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false));
			doReturn(ROUTE).when(strategy).forcedExecutionStrategyName();
			TupleExpr parsed = optimized.expression();
			QueryEvaluationStep compiled = LmdbNativeAggregateCompiler.tryCompile(parsed,
					new QueryEvaluationContext.Minimal((Dataset) null), strategy, counted.source);
			assertThat(compiled).as("the ordinary compiler must retain the complete parsed row query")
					.isInstanceOf(NativeRowsStep.class);
			NativeRowsStep step = (NativeRowsStep) compiled;
			RowState row = new RowState(step.source, step.layout, EmptyBindingSet.getInstance());
			LmdbNativeCostQuote unknownQuote;
			try {
				assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, row.source, row.layout)).isTrue();
				assertThat(step.arg).isInstanceOf(MultiJoinPlan.class);
				MultiJoinPlan join = (MultiJoinPlan) step.arg;
				assertThat(join.children).hasSize(2);
				if (!empty) {
					assertThat(LmdbNativeWork.rowsOut(join, row, row.boundMask()))
							.as("normal compilation must actually produce the zero output estimate under investigation")
							.isZero();
				}
				long beforeQuote = LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get();
				int cursorsBeforeQuote = counted.buildOpens + counted.probeOpens;
				unknownQuote = LmdbNativeKernelHashCostQuote.quote(join, row, Feature.INTERPRETED_ROW, Double.NaN,
						LmdbNativeKernelExecution.rowFillSize(true));
				assertThat(LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get()).isEqualTo(beforeQuote);
				assertThat(counted.buildOpens + counted.probeOpens)
						.as("the quote may inspect metadata but cannot open either input cursor")
						.isEqualTo(cursorsBeforeQuote);
				PatternPlan left = (PatternPlan) join.children[0], right = (PatternPlan) join.children[1];
				LmdbNativeHashJoin.KernelHashPlan planned = LmdbNativeHashJoin.tryPlanKernel(join, left, right, row);
				System.out.printf("hash admission=%s mask=%d replay=%.1f leftRows=%.3f rightRows=%.3f "
						+ "leftWork=%s rightWork=%s leftExpected=%.3f rightExpected=%.3f leftOrder=%s rightOrder=%s%n",
						planned != null, row.boundMask(), LmdbNativeParallelKernelRows.expectedBuildReplays(),
						left.estimateForBoundMask(row.boundMask(), row.source),
						right.estimateForBoundMask(row.boundMask(), row.source),
						left.estimateWork(row, row.boundMask()), right.estimateWork(row, row.boundMask()),
						LmdbNativeWork.expectedWork(left, row, row.boundMask()),
						LmdbNativeWork.expectedWork(right, row, row.boundMask()), left.statementOrder,
						right.statementOrder);
				long mask = row.boundMask();
				double prefix = 1D, chain = 0D;
				for (SlotPlan child : join.derivedPlan(mask).order) {
					PatternPlan pattern = (PatternPlan) child;
					double work = LmdbNativeWork.expectedWork(pattern, row, mask);
					double population = pattern.workRowsForBoundMask(mask, row.source);
					System.out.printf("hash chain predicate=%d mask=%d direct=%s rows=%.6f work=%.3f prefix=%.3f%n",
							pattern.p.constant, mask, pattern.hasDirectEstimateForBoundMask(mask, row.source),
							population, work, prefix);
					chain += prefix * work;
					prefix *= population;
					mask |= pattern.producedMask();
				}
				System.out.printf("hash diagnostic chain=%.3f%n", chain);
				LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerRows(step.arg, row, parsed,
						false);
				assertThat(lowered).isNotNull();
				List<LmdbNativeKernelIr.Node> nodes = new ArrayList<>();
				LmdbNativeKernelIr.visitNodes(lowered.kernel.pipeline, nodes::add);
				assertThat(nodes).anyMatch(LmdbNativeKernelIr.HashProbe.class::isInstance);
				List<LmdbNativeKernelIr.HashBuild> builds = nodes.stream()
						.filter(LmdbNativeKernelIr.HashBuild.class::isInstance)
						.map(LmdbNativeKernelIr.HashBuild.class::cast)
						.toList();
				assertThat(builds).hasSize(1);
				List<LmdbNativeKernelIr.Node> buildNodes = new ArrayList<>();
				LmdbNativeKernelIr.visitNodes(builds.getFirst().pipeline, buildNodes::add);
				assertThat(buildNodes).anySatisfy(node -> {
					assertThat(node).isInstanceOf(LmdbNativeKernelIr.EnumerateAdjKeys.class);
					var keys = (LmdbNativeKernelIr.EnumerateAdjKeys) node;
					assertThat(keys.valueCol).isNotNegative();
					assertThat(lowered.bindings.adjacencies[keys.adjacency].predicate)
							.isEqualTo(counted.buildPredicate);
				});
				assertThat(lowered.kernel.resumable).isTrue();
			} finally {
				row.memoryScope.close();
			}
			assertThat(counted.buildRows).as("compilation and lowering may not execute the build").isZero();
			assertThat(counted.probeRows).as("compilation and lowering may not execute the probe").isZero();
			assertThat(counted.buildOpens + counted.probeOpens).as("all input cursors belong to execution").isZero();
			List<LmdbNativeDecisionRecord.Entry> selected = new ArrayList<>();
			long producedBefore = LmdbNativeKernelExecution.KERNEL_ROWS.get();
			long binds = LmdbNativeKernelExecution.INTERPRETED_BINDS.get();
			long lowerings = LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get();
			LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
				if (record.point() == LmdbNativeDecisionPoint.ROW) {
					assertThat(id).isEqualTo(ROUTE);
					selected.add(
							record.entries().stream().filter(entry -> entry.id().equals(id)).findFirst().orElseThrow());
				}
			});
			Map<Value, Integer> result = new LinkedHashMap<>();
			try (var rows = compiled.evaluate(EmptyBindingSet.getInstance())) {
				assertThat(rows.hasNext()).isEqualTo(!empty);
				assertThat(counted.buildRows).as("all build rows precede the first consumer-visible BindingSet")
						.isEqualTo(BUILD_ROWS);
				assertThat(counted.buildExhaustions).as("the actual hash-build cursor must have reached EOF")
						.isEqualTo(1);
				while (rows.hasNext()) {
					BindingSet bindings = rows.next();
					result.merge(bindings.getValue("value"), 1, Integer::sum);
				}
			} finally {
				LmdbNativeDispatchLoop.observeSelections(null);
			}
			assertThat(optimized.bag()).as("the ordinary optimized repository route's exact answer bag")
					.isEqualTo(expected);
			assertThat(result).as("the opened interpreted hash route's exact answer bag").isEqualTo(expected);
			assertThat(selected).as("exactly one successfully opened ordinary IR candidate").hasSize(1);
			assertThat(LmdbNativeKernelExecution.INTERPRETED_BINDS.get()).isGreaterThan(binds);
			assertThat(LmdbNativeKernelLowering.HASH_JOIN_LOWERINGS.get()).isGreaterThan(lowerings);
			assertThat(counted.buildRows).isEqualTo(BUILD_ROWS);
			assertThat(counted.buildOpens).isEqualTo(1);
			assertThat(counted.buildCloses).as("the drained build cursor is released once")
					.isEqualTo(counted.buildOpens);
			assertThat(counted.probeOpens).isEqualTo(1);
			assertThat(counted.probeCloses)
					.as("the probe cursor is released even when LIMIT stops after the first fill")
					.isEqualTo(counted.probeOpens);
			return new Measured(selected.getFirst().features(), unknownQuote, counted.buildRows, counted.probeRows,
					LmdbNativeKernelExecution.KERNEL_ROWS.get() - producedBefore,
					result.values().stream().mapToInt(Integer::intValue).sum());
		}
	}

	private record Measured(LmdbNativeCostVector features, LmdbNativeCostQuote unknownOutputQuote, int buildRows,
			int probeRows, long producedRows, int consumedRows) {
	}

	/** Capture the real optimizer's cardinalities, never populate a parser tree with fabricated estimates. */
	private Optimized optimizeAndRun(String query) {
		List<TupleExpr> optimized = new ArrayList<>();
		Map<Value, Integer> bag = new LinkedHashMap<>();
		LmdbNativeDispatchLoop.observeSelections((target, label, id, record) -> {
			if (record.point() == LmdbNativeDecisionPoint.ROW) {
				assertThat(id).isEqualTo(ROUTE);
				assertThat(target).isNotNull();
				optimized.add(target.clone());
			}
		});
		try (var connection = repository.getConnection()) {
			SailTupleQuery prepared = (SailTupleQuery) connection.prepareTupleQuery(query);
			prepared.setForcedLmdbExecutionStrategy(ROUTE);
			prepared.setMaxExecutionTime(10);
			try (var rows = prepared.evaluate()) {
				while (rows.hasNext()) {
					bag.merge(rows.next().getValue("value"), 1, Integer::sum);
				}
			}
		} finally {
			LmdbNativeDispatchLoop.observeSelections(null);
		}
		assertThat(optimized).as("one actual optimized repository dispatch").hasSize(1);
		return new Optimized(optimized.getFirst(), bag);
	}

	private record Optimized(TupleExpr expression, Map<Value, Integer> bag) {
	}

	private static Map<Value, Integer> bag(SailRepository repository, String query) {
		Map<Value, Integer> bag = new LinkedHashMap<>();
		try (var connection = repository.getConnection(); var rows = connection.prepareTupleQuery(query).evaluate()) {
			while (rows.hasNext()) {
				bag.merge(rows.next().getValue("value"), 1, Integer::sum);
			}
		}
		return bag;
	}

	private void set(String key, String value) {
		if (!previous.containsKey(key)) {
			previous.put(key, System.getProperty(key));
		}
		System.setProperty(key, value);
	}

	/**
	 * Delegates every data/metadata operation to the actual snapshot and only observes the physical producer cursors.
	 */
	private static final class CountedSource {
		final NativeLmdbQuerySource source;
		final long buildPredicate;
		final long probePredicate;
		int buildRows, buildExhaustions, buildOpens, buildCloses, probeRows, probeOpens, probeCloses;

		CountedSource(NativeLmdbQuerySource actual, long buildPredicate, long probePredicate) throws IOException {
			this.buildPredicate = buildPredicate;
			this.probePredicate = probePredicate;
			source = mock(NativeLmdbQuerySource.class, delegatesTo(actual));
			doAnswer(open -> {
				NativeProbe realProbe = actual.newProbe();
				NativeProbe probe = mock(NativeProbe.class, delegatesTo(realProbe));
				doAnswer(request -> {
					long predicate = request.getArgument(0);
					boolean bySubject = request.getArgument(1);
					NativeAdjacency realView = realProbe.adjacency(predicate, bySubject);
					if ((predicate != buildPredicate && predicate != probePredicate) || realView == null) {
						return realView;
					}
					NativeAdjacency view = mock(NativeAdjacency.class, delegatesTo(realView));
					doAnswer(cursorOpen -> {
						KeyRunCursor actualCursor = realView.openKeyRunCursor();
						assertThat(actualCursor).isNotNull();
						if (predicate == buildPredicate) {
							buildOpens++;
						} else {
							probeOpens++;
						}
						KeyRunCursor cursor = mock(KeyRunCursor.class, delegatesTo(actualCursor));
						doAnswer(advance -> {
							boolean available = actualCursor.advance();
							if (available) {
								assertThat(actualCursor.runSize()).isEqualTo(1L);
								if (predicate == buildPredicate) {
									buildRows++;
								} else {
									probeRows++;
								}
							} else if (predicate == buildPredicate) {
								buildExhaustions++;
							}
							return available;
						}).when(cursor).advance();
						doAnswer(close -> {
							actualCursor.close();
							if (predicate == buildPredicate) {
								buildCloses++;
							} else {
								probeCloses++;
							}
							return null;
						}).when(cursor).close();
						return cursor;
					}).when(view).openKeyRunCursor();
					return view;
				}).when(probe).adjacency(anyLong(), anyBoolean());
				return probe;
			}).when(source).newProbe();
		}
	}
